@r1.c1 w.request.constraint request=$r1 on=attribute attribute=drawn.direction value=right operator=eq phase=result
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=drawn.direction value=down operator=eq phase=result
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=drawn.direction value=left operator=eq phase=result
@r1.c4 w.request.constraint request=$r1 on=place attribute=drawn.relation value=under operator=relation phase=result
@r1.c5 w.request.constraint request=$r1 on=place attribute=drawn.anchor value="the boat" operator=relation phase=selector
@r1.u1 w.request.unread request=$r1 text="get the kite to the right, then down, then left until it is under the boat" note=drawn.path

